import { replaceSlashIndex } from '../slug/replaceSlashIndex.js';
import { isPage } from './isPage.js';
const normalizeNavPath = (p) => replaceSlashIndex(p.replace(/^\/+/, '').replace(/\/+$/, ''));
const hrefOf = (node) => isPage(node) ? node.href : 'href' in node ? node.href : undefined;
export function decoratedNavDivisions(node) {
    if (isPage(node))
        return [];
    if ('languages' in node)
        return node.languages;
    if ('versions' in node)
        return node.versions;
    if ('products' in node)
        return node.products;
    if ('tabs' in node)
        return node.tabs;
    if ('anchors' in node)
        return node.anchors;
    if ('dropdowns' in node)
        return node.dropdowns;
    return [];
}
export function decoratedNavChildren(node) {
    if (isPage(node))
        return [];
    if ('group' in node)
        return node.root ? [node.root, ...node.pages] : node.pages;
    if ('pages' in node)
        return node.pages;
    if ('groups' in node)
        return node.groups;
    if ('menu' in node)
        return node.menu;
    return [];
}
const matches = (node, path) => {
    const href = hrefOf(node);
    return href !== undefined && normalizeNavPath(href) === path;
};
function contains(node, path) {
    if (matches(node, path))
        return true;
    return (decoratedNavChildren(node).some((c) => contains(c, path)) ||
        decoratedNavDivisions(node).some((c) => contains(c, path)));
}
function findPage(node, path) {
    if (isPage(node))
        return matches(node, path) ? { title: node.title, mode: node.mode } : null;
    for (const child of [...decoratedNavChildren(node), ...decoratedNavDivisions(node)]) {
        const found = findPage(child, path);
        if (found)
            return found;
    }
    return null;
}
export const decoratedNavContains = (node, path) => contains(node, normalizeNavPath(path));
export const findDecoratedNavPage = (node, path) => findPage(node, normalizeNavPath(path));
// reachable through groups and pages alone, without entering a division
function containsDirect(node, path) {
    return matches(node, path) || decoratedNavChildren(node).some((c) => containsDirect(c, path));
}
// the nodes whose own pages (not a nested division's) hold the path: the
// root for a flat nav, else the innermost division chain down to the page.
// a child that only reaches the path through divisions of its own (a menu
